function rsv2_entity(string $v):string{$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))rsv2_out(['ok'=>false,'error'=>'Salary and mill rent are available for TTI / BRM.'],422);return $v;}
