function rsv2_amt(mixed $v,string $label='Amount'):float{$n=is_numeric($v)?round((float)$v,2):0;if(!is_finite($n)||$n<=0||$n>100000000000)rsv2_out(['ok'=>false,'error'=>$label.' must be greater than zero.'],422);return $n;}
