/** Opening debt only: no fresh cash payment and no salary expense. */
function rsv2_opening_advance(array &$s,string $entity,array $b,array $u,array $names):array {
    if(!in_array($u['role']??'',['Super Admin','Director'],true)||(($u['role']??'')==='Director'&&!tt_user_can_access_entity($u,$entity,'Approve')))throw new DomainException('Management permission is required for salary opening advances.');
