    foreach((array)$s['salaryAdvances'] as $a)if(($a['entity']??'')===$entity&&($a['masterId']??'')===$mid&&($a['openingBalance']??false))throw new DomainException('This person already has a salary advance brought forward. Review its original Post ID.');
